-- Add CONTRACTS_OFFICER and ACCOUNTANT roles to role_permissions

-- Drop the existing check constraint so we can extend it
ALTER TABLE role_permissions DROP CONSTRAINT IF EXISTS role_permissions_role_check;

-- Add updated check constraint with new roles
ALTER TABLE role_permissions
    ADD CONSTRAINT role_permissions_role_check
    CHECK (role IN ('SUPER_ADMIN','PROPERTY_ADMIN','MAINTENANCE_OFFICER','TENANT',
                    'CONTRACTS_OFFICER','ACCOUNTANT'));

-- Insert default permissions for new roles
INSERT INTO role_permissions (role, permissions_json, created_at, updated_at)
